annotate ProductService.Products with @(
  UI: {
    HeaderInfo: {
      TypeName       : 'Product',
      TypeNamePlural : 'Products',
      Title          : { Value: name },
      Description    : { Value: category.name }
    },
    SelectionFields: [ category_ID, price, status ],
    LineItem: [
      { Value: name,          Label: 'Product'  },
      { Value: category.name, Label: 'Category' },
      { Value: price,         Label: 'Price'    },
      { Value: status,        Criticality: statusCriticality },
      { $Type: 'UI.DataFieldForAction', Action: 'ProductService.approve', Label: 'Approve' }
    ],
    Facets: [
      { $Type: 'UI.ReferenceFacet', Label: 'General', Target: '@UI.FieldGroup#General' },
      { $Type: 'UI.ReferenceFacet', Label: 'Items',   Target: 'items/@UI.LineItem' }
    ],
    FieldGroup #General: {
      Data: [ { Value: name }, { Value: description }, { Value: price } ]
    }
  }
);

annotate ProductService.Products with {
  name     @Common.Label: 'Product Name';
  category @Common.Text: category.name
           @Common.ValueList: { entity: 'Categories', type: #fixed };
};

"routing": {
  "routes": [
    { "name": "ProductsList",   "pattern": ":?query:",                "target": "ProductsList" },
    { "name": "ProductsObject", "pattern": "Products({key}):?query:", "target": "ProductsObject" }
  ],
  "targets": {
    "ProductsList": {
      "type": "Component",
      "id": "ProductsList",
      "name": "sap.fe.templates.ListReport",
      "options": {
        "settings": {
          "contextPath": "/Products",
          "variantManagement": "Page",
          "initialLoad": "Enabled",
          "navigation": {
            "Products": { "detail": { "route": "ProductsObject" } }
          },
          "controlConfiguration": {
            "@com.sap.vocabularies.UI.v1.LineItem": {
              "tableSettings": {
                "type": "ResponsiveTable",
                "selectionMode": "Multi",
                "personalization": { "column": true, "sort": true, "filter": true }
              }
            }
          }
        }
      }
    },
    "ProductsObject": {
      "type": "Component",
      "id": "ProductsObject",
      "name": "sap.fe.templates.ObjectPage",
      "options": {
        "settings": {
          "contextPath": "/Products",
          "editableHeaderContent": false,
          "sectionLayout": "Tabs"
        }
      }
    }
  }
}

sap.ui.define([
  "sap/ui/core/mvc/ControllerExtension",
  "sap/ui/core/Messaging"
], function (ControllerExtension, Messaging) {
  "use strict";
  return {
    // registered for sap.suite.ui.generic.template.ObjectPage.view.Details
    adaptTransientMessageExtension: function () {
      Messaging.getMessageModel().getData().forEach(function (message) {
        if (message.getCode() === "ZSD/012") {
          message.setMessage("The order was released and the customer has been notified.");
        }
      });
    }
  };
});

