service ProductService {
  @odata.draft.enabled
  entity Products as projection on db.Products;
}

// Display -> [Edit]   -> draft created (private copy, locked to this user)
//         -> edits are saved continuously into the draft
//         -> [Save]   -> draft activated, becomes the active record
//         -> [Cancel] -> draft discarded, the active record is untouched

import PageController from "sap/fe/core/PageController";

/**
 * @namespace my.app.ext
 */
export default class CustomPage extends PageController {
  public onInit(): void {
    super.onInit();
    // this.getExtensionAPI() gives access to edit flow, routing, messages
  }
}

"controlConfiguration": {
  "@com.sap.vocabularies.UI.v1.LineItem": {
    "columns": {
      "customStatus": {
        "header": "{i18n>statusColumn}",
        "position": { "placement": "After", "anchor": "DataField::price" },
        "template": "my.app.ext.fragment.StatusColumn",
        "properties": ["status", "statusText"],
        "width": "8rem"
      }
    }
  }
},
"content": {
  "body": {
    "sections": {
      "customHistory": {
        "title": "{i18n>historySection}",
        "position": { "placement": "After", "anchor": "GeneralSection" },
        "template": "my.app.ext.view.HistorySection"
      }
    }
  },
  "header": {
    "actions": {
      "customPrint": {
        "text": "{i18n>print}",
        "press": "my.app.ext.controller.Actions.onPrint",
        "requiresSelection": false
      }
    }
  }
}

// manifest.json -> sap.ui5/extends/extensions/sap.ui.controllerExtensions:
// "sap.fe.templates.ObjectPage.ObjectPageController": { "controllerName": "my.app.ext.controller.ObjectPageExt" }

sap.ui.define(["sap/ui/core/mvc/ControllerExtension"], function (ControllerExtension) {
  "use strict";
  return ControllerExtension.extend("my.app.ext.controller.ObjectPageExt", {
    override: {
      onInit: function () { /* runs in addition to the template's onInit */ },
      editFlow: {
        onBeforeSave: function (oEvent) {
          // validate before the draft is activated; return a rejected promise to stop
        },
        onAfterSave: function (oEvent) { }
      },
      routing: {
        onAfterBinding: function (oContext) { }
      }
    }
  });
});
